name: Auto-close PRs targeting unready issues

on:
  pull_request:
    types: [opened, edited, synchronize, reopened]

permissions:
  pull-requests: write
  contents: read

jobs:
  check-unready-issue:
    runs-on: ubuntu-latest
    if: ${{ github.event.pull_request.user.type != 'Bot' && !contains(github.event.pull_request.labels.*.name, 'maintainer') }}
    steps:
      - name: Check for unready issue reference
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const pr = context.payload.pull_request;
            const body = pr.body || "";

            // Extract issue references (#123 or full URLs)
            const issueRegex = /#(\d+)|https?:\/\/github\.com\/mlflow\/mlflow\/issues\/(\d+)/g;
            const matches = [...body.matchAll(issueRegex)];

            // Skip if no issues referenced
            if (matches.length === 0) {
              console.log("No issue references found in PR body.");
              return;
            }

            // Collect unique issue numbers
            const issueNumbers = new Set();
            for (const match of matches) {
              const num = match[1] || match[2];
              if (num) issueNumbers.add(parseInt(num));
            }

            // Skip if multiple issues referenced (ambiguous intent)
            if (issueNumbers.size > 1) {
              console.log(`Multiple issues referenced: ${[...issueNumbers].join(', ')}. Skipping.`);
              return;
            }

            const issueNumber = [...issueNumbers][0];
            console.log(`Referenced issue: #${issueNumber}`);

            // Fetch issue details
            const issue = await github.rest.issues.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issueNumber
            });

            const issueData = issue.data;

            // Skip issues created before 2026-03-10
            const cutoffDate = new Date("2026-03-10T00:00:00Z");
            const issueCreatedAt = new Date(issueData.created_at);
            if (issueCreatedAt < cutoffDate) {
              console.log(`Issue #${issueNumber} created before policy date. Skipping.`);
              return;
            }

            // Check if 'ready' label is present
            const labels = issueData.labels.map(l => l.name);
            if (labels.includes('ready')) {
              console.log(`Issue #${issueNumber} has 'ready' label. Skipping.`);
              return;
            }

            // Issue is unready, close the PR
            const comment = `🚫 **This PR references issue #${issueNumber}, which has not been triaged yet.**

Please wait until the issue is labeled with \`ready\` before submitting a PR. This ensures that the maintainers have reviewed the issue and confirmed it's ready for implementation.

You can reopen this PR once the issue is labeled \`ready\`.`;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              body: comment
            });

            await github.rest.pulls.update({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: pr.number,
              state: 'closed'
            });

            console.log(`PR #${pr.number} closed due to unready issue #${issueNumber}.`);
```

